import{_ as e,c as a,a2 as p,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第十四章 怎么样做才能睡个好觉？","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/14第十四章 怎么样做才能睡个好觉.md","filePath":"meditation/巴利文大藏经/14第十四章 怎么样做才能睡个好觉.md"}'),_={name:"meditation/巴利文大藏经/14第十四章 怎么样做才能睡个好觉.md"};function r(n,t,i,s,d,c){return o(),a("div",null,t[0]||(t[0]=[p('<h1 id="第十四章-怎么样做才能睡个好觉" tabindex="-1">第十四章 怎么样做才能睡个好觉？ <a class="header-anchor" href="#第十四章-怎么样做才能睡个好觉" aria-label="Permalink to &quot;第十四章 怎么样做才能睡个好觉？&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部3相应14经/战斗经第一(憍萨罗相应/有偈篇/祇夜)</p><p>有个时候，摩揭陀国的阿闍世王突然率领军队偷袭了迦尸国，并且在占领迦尸国后，又继续入侵骄萨罗国。骄萨罗国的军队被攻击后，波斯匿王仓促的率领军队，准备抵御阿闍世王军队的入侵。</p><p>由于事发突然，波斯匿王毫无准备，他率领的军队又没有战心，很快阿闍世王的军队就打败了波斯匿王的军队。于是，波斯匿王就率领败军退守骄萨罗国的首都舍卫城。</p><p>那个时候，有很多出家人，他们在中午前，穿上法衣，拿着饭钵，到舍卫城里化缘饭食，他们吃完化缘来的饭食后，就来到佛陀的住所，顶礼佛陀后，这些出家人中的长老就对佛陀说：“世尊，我们今天外出化缘饭食的时候，看见舍卫城里到处都是士兵，城里的老百姓也在帮助军队加固城墙，我们听说摩揭陀国的阿闍世王突袭、占领了迦尸国，他们的军队之后又入侵了骄萨罗国，波斯匿王仓促的率领军队抵御阿闍世王军队的入侵，可是由于波斯匿王毫无准备的缘故，他率领的军队吃了败仗，之后，波斯匿王只好率领余下的军队退守首都舍卫城。”</p><p>佛陀对这些出家人说：“摩揭陀国的阿闍世王他的身边有贪得无厌的恶盟友、恶大臣、恶友相伴，让他自己也被贪欲蒙蔽了双眼，由此发动战争侵占别国的领土。而骄萨罗国的波斯匿王虽然与善盟友、善大臣、善友相伴，可是他的军队准备不足，对于阿闍世王军队的入侵毫无防备，因此而失败。</p><p>弟子们，今天晚上对于波斯匿王来说是漫漫的长夜呀，他多半是夜不能眠的，他多半是忧心忡忡、睡不好觉的，获得战争胜利的国王和军队会种下仇恨的种子，最终结出怨恨报复的恶果，而战争失败的国王和军队就会因此忧心忡忡、夜不能眠、睡不好觉。只有内心不再有成与败、胜利与失败的人；只有内心不再有得失、挂念和执着的人，没有贪欲的人，内心才不会生起烦恼和痛苦，这样没有烦恼和痛苦的人才能清净安宁的睡好觉。”</p><p>这时，佛陀说偈言：</p><p>「胜利以生怨，败者苦难寝。</p><p>只有舍胜败，平静乐安眠。」</p>',11)]))}const f=e(_,[["render",r]]);export{m as __pageData,f as default};
